-- ============================================================
--  JRS Core - Free Edition - DATABASE
--  Tables for: jrs_core, jrs_inventory, jrs_character,
--              jrs_clothing, jrs_barber, jrs_loadingscreen
--  Seed data : jrs_items (item catalogue)
--  Import into an EMPTY database (txAdmin recipe does this for you).
-- ============================================================

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
SET SQL_MODE = 'NO_AUTO_VALUE_ON_ZERO';


-- ---------------- jrs_admin_character_scale
CREATE TABLE IF NOT EXISTS `jrs_admin_character_scale` (
  `character_id` int(11) NOT NULL,
  `scale` decimal(4,2) NOT NULL,
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`character_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------- jrs_appearance_legacy_backup
CREATE TABLE IF NOT EXISTS `jrs_appearance_legacy_backup` (
  `charid` int(11) NOT NULL,
  `compPlayer` longtext NOT NULL,
  `skinPlayer` longtext NOT NULL,
  `migrated_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`charid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------- jrs_appearance_onboarding
CREATE TABLE IF NOT EXISTS `jrs_appearance_onboarding` (
  `charid` int(11) NOT NULL,
  `stage` varchar(32) NOT NULL DEFAULT 'clothing',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`charid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------- jrs_bans
CREATE TABLE IF NOT EXISTS `jrs_bans` (
  `identifier` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `date` datetime DEFAULT NULL ON UPDATE current_timestamp(),
  KEY `identifier` (`identifier`),
  KEY `reason` (`reason`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;

-- ---------------- jrs_barber
CREATE TABLE IF NOT EXISTS `jrs_barber` (
  `charid` int(11) NOT NULL,
  `hairstyle` longtext NOT NULL,
  `overlays` longtext NOT NULL,
  `permanentoverlay` longtext NOT NULL,
  `outfit_id` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`charid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------- jrs_barber_preset
CREATE TABLE IF NOT EXISTS `jrs_barber_preset` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `charid` int(11) NOT NULL,
  `outfit_id` varchar(50) NOT NULL,
  `price` decimal(10,2) NOT NULL DEFAULT 0.00,
  `name` varchar(255) NOT NULL DEFAULT '',
  `hairstyle` longtext NOT NULL,
  `overlays` longtext NOT NULL,
  `gender` varchar(32) NOT NULL DEFAULT '',
  PRIMARY KEY (`id`),
  UNIQUE KEY `jrs_barber_preset_outfit_unique` (`outfit_id`),
  KEY `jrs_barber_preset_charid_idx` (`charid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------- jrs_character_creator
CREATE TABLE IF NOT EXISTS `jrs_character_creator` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `charid` int(11) NOT NULL,
  `peddata` longtext NOT NULL,
  `informations` longtext NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `jrs_character_creator_charid_unique` (`charid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------- jrs_characters
CREATE TABLE IF NOT EXISTS `jrs_characters` (
  `identifier` varchar(50) NOT NULL DEFAULT '',
  `charidentifier` int(11) NOT NULL AUTO_INCREMENT,
  `money` double(11,2) DEFAULT 15.00,
  `dirtymoney` decimal(20,2) NOT NULL DEFAULT 0.00,
  `gold` double(11,2) DEFAULT 0.15,
  `rol` double(11,2) NOT NULL DEFAULT 0.00,
  `inventory` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `job` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT 'unemployed',
  `status` varchar(140) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '{}',
  `meta` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '{}',
  `firstname` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT ' ',
  `lastname` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT ' ',
  `skinPlayer` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `compPlayer` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `jobgrade` int(11) DEFAULT 0,
  `coords` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '{}',
  `isdead` tinyint(1) DEFAULT 0,
  `walking_style` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT 'Default',
  `walk` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT 'MP_Style_Casual',
  `furniture` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT '[]',
  `hotbar` text DEFAULT NULL,
  `dateofbirth` date DEFAULT NULL,
  `nickname` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `occupation` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `playtime_seconds` bigint(20) unsigned NOT NULL DEFAULT 0,
  `base_age` smallint(5) unsigned DEFAULT NULL,
  `age_years` smallint(5) unsigned DEFAULT NULL,
  `multijobs` longtext DEFAULT NULL,
  `skills` longtext DEFAULT NULL,
  `onduty` tinyint(1) NOT NULL DEFAULT 0,
  `character_desc` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `gender` varchar(16) DEFAULT NULL,
  `last_played` timestamp NULL DEFAULT NULL,
  `appearance_version` int(11) NOT NULL DEFAULT 1,
  `health_state` longtext DEFAULT NULL,
  UNIQUE KEY `identifier_charidentifier` (`identifier`,`charidentifier`) USING BTREE,
  KEY `charidentifier` (`charidentifier`) USING BTREE,
  KEY `coords` (`coords`(768)),
  KEY `compPlayer` (`compPlayer`(768)),
  KEY `skinPlayer` (`skinPlayer`(768)),
  KEY `money` (`money`),
  KEY `status` (`status`),
  CONSTRAINT `FK_characters_users` FOREIGN KEY (`identifier`) REFERENCES `jrs_users` (`identifier`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci ROW_FORMAT=DYNAMIC;

-- ---------------- jrs_characters_level
CREATE TABLE IF NOT EXISTS `jrs_characters_level` (
  `CharIdentifier` int(11) NOT NULL,
  `XP` bigint(20) unsigned NOT NULL DEFAULT 0,
  PRIMARY KEY (`CharIdentifier`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- ---------------- jrs_clothing_current
CREATE TABLE IF NOT EXISTS `jrs_clothing_current` (
  `charid` int(11) NOT NULL,
  `clothes` longtext NOT NULL,
  `outfit_id` varchar(50) DEFAULT NULL,
  `hidden_categories` longtext DEFAULT NULL,
  PRIMARY KEY (`charid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------- jrs_clothing_outfits
CREATE TABLE IF NOT EXISTS `jrs_clothing_outfits` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `charid` int(11) NOT NULL,
  `outfit_id` varchar(50) DEFAULT NULL,
  `price` decimal(10,2) NOT NULL DEFAULT 0.00,
  `name` varchar(255) NOT NULL DEFAULT '',
  `clothes` longtext NOT NULL,
  `singleitems` longtext NOT NULL,
  `gender` varchar(32) NOT NULL DEFAULT '',
  PRIMARY KEY (`id`),
  UNIQUE KEY `jrs_clothing_outfit_unique` (`outfit_id`),
  KEY `jrs_clothing_outfit_charid_idx` (`charid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------- jrs_clothing_wearables
CREATE TABLE IF NOT EXISTS `jrs_clothing_wearables` (
  `charid` int(11) NOT NULL,
  `outfit_id` varchar(50) NOT NULL,
  `skin` longtext NOT NULL,
  PRIMARY KEY (`charid`,`outfit_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------- jrs_core_hud_layouts
CREATE TABLE IF NOT EXISTS `jrs_core_hud_layouts` (
  `identifier` varchar(100) NOT NULL,
  `charidentifier` int(11) NOT NULL,
  `layout` longtext NOT NULL,
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`identifier`,`charidentifier`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------- jrs_discord_whitelist
CREATE TABLE IF NOT EXISTS `jrs_discord_whitelist` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `identifier` varchar(64) NOT NULL,
  `added_by` varchar(64) DEFAULT 'System',
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `identifier` (`identifier`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------- jrs_double_xp_state
CREATE TABLE IF NOT EXISTS `jrs_double_xp_state` (
  `id` tinyint(3) unsigned NOT NULL DEFAULT 1,
  `active` tinyint(1) NOT NULL DEFAULT 0,
  `multiplier` decimal(8,2) NOT NULL DEFAULT 1.00,
  `started_at` bigint(20) NOT NULL DEFAULT 0,
  `ends_at` bigint(20) NOT NULL DEFAULT 0,
  `started_by` varchar(128) NOT NULL DEFAULT '',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------- jrs_drops
CREATE TABLE IF NOT EXISTS `jrs_drops` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `drop_list` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;

-- ---------------- jrs_id_numbers
CREATE TABLE IF NOT EXISTS `jrs_id_numbers` (
  `charid` varchar(64) NOT NULL,
  `identity_number` char(6) NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`charid`),
  UNIQUE KEY `uniq_identity_number` (`identity_number`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------- jrs_idcard
CREATE TABLE IF NOT EXISTS `jrs_idcard` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `charid` varchar(64) NOT NULL DEFAULT '',
  `identity_number` char(6) NOT NULL DEFAULT '',
  `picture` longtext NOT NULL DEFAULT '',
  `name` varchar(100) NOT NULL DEFAULT '',
  `city` varchar(100) NOT NULL DEFAULT '',
  `birthday1` varchar(20) NOT NULL DEFAULT '',
  `age` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `complexion` varchar(40) NOT NULL DEFAULT '',
  `eyes` varchar(40) NOT NULL DEFAULT '',
  `height` varchar(20) NOT NULL DEFAULT '',
  `birthday2` varchar(20) NOT NULL DEFAULT '',
  `birth1` varchar(80) NOT NULL DEFAULT '',
  `birth2` varchar(80) NOT NULL DEFAULT '',
  `birth3` varchar(80) NOT NULL DEFAULT '',
  `hair` varchar(40) NOT NULL DEFAULT '',
  `nationality` varchar(100) NOT NULL DEFAULT '',
  `marks` varchar(500) NOT NULL DEFAULT '',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------- jrs_inventory_storage
CREATE TABLE IF NOT EXISTS `jrs_inventory_storage` (
  `identifier` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `charid` int(11) NOT NULL DEFAULT 0,
  `items` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '{}',
  `size` double DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;

-- ---------------- jrs_items
CREATE TABLE IF NOT EXISTS `jrs_items` (
  `item` varchar(50) NOT NULL,
  `label` varchar(50) NOT NULL,
  `label_ar` varchar(100) DEFAULT NULL,
  `limit` decimal(10,2) NOT NULL DEFAULT 1.00,
  `can_remove` tinyint(1) NOT NULL DEFAULT 1,
  `type` varchar(50) DEFAULT NULL,
  `usable` tinyint(1) DEFAULT NULL,
  `descriptions` varchar(255) DEFAULT NULL,
  `descriptions_ar` varchar(255) DEFAULT NULL,
  `metadata` varchar(1) NOT NULL DEFAULT '0',
  `category` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`item`) USING BTREE,
  KEY `label` (`label`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- ---------------- jrs_job_levels
CREATE TABLE IF NOT EXISTS `jrs_job_levels` (
  `charidentifier` int(11) NOT NULL,
  `job` varchar(40) NOT NULL,
  `xp` int(11) NOT NULL DEFAULT 0,
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`charidentifier`,`job`),
  KEY `idx_jrs_job_levels_char` (`charidentifier`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------- jrs_job_xp_shares
CREATE TABLE IF NOT EXISTS `jrs_job_xp_shares` (
  `job` varchar(40) NOT NULL,
  `core_share` decimal(6,4) NOT NULL DEFAULT 0.2500,
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`job`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------- jrs_metabolism
CREATE TABLE IF NOT EXISTS `jrs_metabolism` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `charidentifier` varchar(50) NOT NULL,
  `meta` longtext NOT NULL,
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `hud_settings` longtext DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `charidentifier` (`charidentifier`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------- jrs_npc_outfits
CREATE TABLE IF NOT EXISTS `jrs_npc_outfits` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `identifier` varchar(100) NOT NULL,
  `charid` int(11) NOT NULL,
  `name` varchar(80) NOT NULL,
  `ped_model` varchar(100) NOT NULL,
  `ped_hash` bigint(20) NOT NULL DEFAULT 0,
  `gender` varchar(8) NOT NULL DEFAULT 'male',
  `outfit_preset` int(11) DEFAULT NULL,
  `components` longtext NOT NULL,
  `component_count` int(11) NOT NULL DEFAULT 0,
  `is_deleted` tinyint(1) NOT NULL DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_jrs_npc_outfits_owner` (`identifier`,`charid`,`is_deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------- jrs_organizations
CREATE TABLE IF NOT EXISTS `jrs_organizations` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(50) NOT NULL,
  `graffiti_model` varchar(50) NOT NULL,
  `money` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_jrs_organizations_name` (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------- jrs_ranch
CREATE TABLE IF NOT EXISTS `jrs_ranch` (
  `farmid` varchar(64) NOT NULL,
  `location_id` varchar(64) DEFAULT NULL,
  `funds` bigint(20) NOT NULL DEFAULT 0,
  `owner_steam` varchar(64) DEFAULT NULL,
  `owner_name` varchar(128) DEFAULT NULL,
  `price_paid` bigint(20) NOT NULL DEFAULT 0,
  `purchased_at` bigint(20) DEFAULT NULL,
  `farm_condition` smallint(6) NOT NULL DEFAULT 100,
  `last_condition_at` bigint(20) DEFAULT NULL,
  `tax_last_at` bigint(20) DEFAULT NULL,
  `tax_next_at` bigint(20) DEFAULT NULL,
  `tax_last_paid_at` bigint(20) DEFAULT NULL,
  `tax_due_amount` bigint(20) NOT NULL DEFAULT 0,
  `tax_unpaid_cycles` int(11) NOT NULL DEFAULT 0,
  `herd_locked` tinyint(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`farmid`),
  KEY `idx_owner` (`owner_steam`),
  KEY `idx_location_owner` (`location_id`,`owner_steam`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------- jrs_stashes
CREATE TABLE IF NOT EXISTS `jrs_stashes` (
  `stash_id` int(11) NOT NULL AUTO_INCREMENT,
  `storage_id` varchar(190) NOT NULL,
  `owner_charid` int(11) NOT NULL DEFAULT 0,
  `owner_identifier` varchar(100) DEFAULT NULL,
  `owner_name` varchar(100) DEFAULT NULL,
  `stash_size` decimal(12,2) NOT NULL DEFAULT 1000.00,
  `price_money` decimal(14,2) NOT NULL DEFAULT 0.00,
  `price_gold` decimal(14,2) NOT NULL DEFAULT 0.00,
  `stash_coords` longtext NOT NULL,
  `stash_users` longtext NOT NULL,
  `webhook` longtext DEFAULT NULL,
  `source_item` varchar(64) DEFAULT NULL,
  `created_by` varchar(100) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`stash_id`),
  UNIQUE KEY `uq_jrs_stashes_storage_id` (`storage_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------- jrs_trade_orders
CREATE TABLE IF NOT EXISTS `jrs_trade_orders` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `trade_key` varchar(64) NOT NULL,
  `seller_identifier` varchar(128) NOT NULL,
  `seller_charid` varchar(128) NOT NULL,
  `seller_name` varchar(128) DEFAULT NULL,
  `buyer_identifier` varchar(128) NOT NULL,
  `buyer_charid` varchar(128) NOT NULL,
  `buyer_name` varchar(128) DEFAULT NULL,
  `price` bigint(20) unsigned NOT NULL DEFAULT 0,
  `status` varchar(32) NOT NULL DEFAULT 'locked',
  `offer_json` longtext NOT NULL,
  `buyer_charged` tinyint(1) NOT NULL DEFAULT 0,
  `delivered` tinyint(1) NOT NULL DEFAULT 0,
  `seller_paid` tinyint(1) NOT NULL DEFAULT 0,
  `cancel_reason` varchar(64) DEFAULT NULL,
  `expires_at` datetime DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_jrs_trade_key` (`trade_key`),
  KEY `idx_jrs_trade_seller` (`seller_identifier`,`seller_charid`,`status`),
  KEY `idx_jrs_trade_buyer` (`buyer_identifier`,`buyer_charid`,`status`),
  KEY `idx_jrs_trade_expiry` (`status`,`expires_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------- jrs_users
CREATE TABLE IF NOT EXISTS `jrs_users` (
  `identifier` varchar(50) NOT NULL,
  `honor` int(11) NOT NULL DEFAULT 100,
  `group` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT 'user',
  `warnings` int(11) DEFAULT 0,
  `banned` tinyint(4) DEFAULT 0,
  `chars` int(1) DEFAULT 1,
  `chars_override` int(11) DEFAULT NULL,
  `language` varchar(8) DEFAULT NULL,
  PRIMARY KEY (`identifier`) USING BTREE,
  UNIQUE KEY `identifier` (`identifier`) USING BTREE,
  KEY `group` (`group`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;

-- ---------------- jrs_weaponloadout
CREATE TABLE IF NOT EXISTS `jrs_weaponloadout` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `serial_number` varchar(64) DEFAULT NULL,
  `identifier` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `charidentifier` int(11) DEFAULT NULL,
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `ammo` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '{}',
  `dirtlevel` double DEFAULT 0,
  `conditionlevel` double DEFAULT 0,
  `no_break` tinyint(1) NOT NULL DEFAULT 0,
  `used` tinyint(4) DEFAULT 0,
  `slot` int(11) NOT NULL DEFAULT 1,
  `comps` varchar(15000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '{}',
  `stolen` tinyint(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uniq_weapon_serial` (`serial_number`),
  KEY `id` (`id`) USING BTREE,
  KEY `identifier` (`identifier`),
  KEY `charidentifier` (`charidentifier`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;

-- ---------------- jrs_whitelist
CREATE TABLE IF NOT EXISTS `jrs_whitelist` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `identifier` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `identifier` (`identifier`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;

-- ---------------- jrs_tax_ledger
CREATE TABLE IF NOT EXISTS `jrs_tax_ledger` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `receipt_id` varchar(64) NOT NULL,
  `charidentifier` varchar(64) NOT NULL,
  `category` varchar(64) DEFAULT NULL,
  `base_amount` decimal(20,2) NOT NULL DEFAULT 0.00,
  `tax_amount` decimal(20,2) NOT NULL DEFAULT 0.00,
  `total_amount` decimal(20,2) NOT NULL DEFAULT 0.00,
  `resource_name` varchar(100) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_charid` (`charidentifier`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- ---------------- jrs_tax_debts
CREATE TABLE IF NOT EXISTS `jrs_tax_debts` (
  `charidentifier` varchar(64) NOT NULL,
  `unpaid_tax` decimal(20,2) NOT NULL DEFAULT 0.00,
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`charidentifier`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- ---------------- jrs_economy_logs
CREATE TABLE IF NOT EXISTS `jrs_economy_logs` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `charidentifier` varchar(64) DEFAULT NULL,
  `action_type` varchar(64) DEFAULT NULL,
  `amount` decimal(20,2) DEFAULT 0.00,
  `currency` varchar(16) DEFAULT NULL,
  `metadata` longtext DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_charid` (`charidentifier`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

